// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address to1, address to2, uint256 v) public {
        vm.assume(caddress != address(0));
        vm.assume(to1 != address(0));
        vm.assume(to2 != address(0));
        address[] memory tos = new address[](2);
        tos[0] = to1;
        tos[1] = to2;
        bool ok = c.transfer(from, caddress, tos, v);
        assertTrue(ok);
    }
}
